INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BiPlane 4', 'The game requires four players. Play consists of a black and a white BiPlane that is steered like a tank. The object is to shoot the other players without crashing into either the ground or the anti-aircraft fire at the top of the screen.' FROM games WHERE igdb_id = 112890 ON CONFLICT (game_id, language_code) DO NOTHING;
