INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Videocart-1: Tic-Tac-Toe & Shooting Gallery & Doodle & Quadra-Doodle', 'Videocart-1: Tic Tac Toe, Shooting Gallery, Doodle, Quadradoodle is a board game genre video game released in 1976 by Fairchild Semiconductor for the Fairchild Channel F. This preprogrammed cartridge plugs into the console of the Fairchild Video Entertainment System for more TV fun with these exciting solo games.' FROM games WHERE igdb_id = 41222 ON CONFLICT (game_id, language_code) DO NOTHING;
