INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flyball', 'Flyball is a baseball arcade game which was released by Atari in 1976. Both players must use an analogue joystick, 1P bats first and 2P pitches first, to control their players with one button to make them bat and pitch for the members of the batting team will run round the bases automatically - and unlike in real baseball matches, the game shall only last for one (or two) innings.' FROM games WHERE igdb_id = 40329 ON CONFLICT (game_id, language_code) DO NOTHING;
