INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nurburgring-1', 238207, '1976-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co65xy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sclc9s.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nurburgring-1', 'Considered by many to be the first fully electronic, first-person driving simulator, this was Dr. Reiner Forest''s attempt at miniaturizing the racecar driving experience. It directly inspired Ted Michon''s game Night Racer, which in turn led to him working with Midway to create 280 Zzzap around the same time. Meanwhile, Atari designer Dave Sheppard saw a screenshot of what was very likely Nürburgring 1 in a magazine; this led to the company''s own iteration, the better-known Night Driver. The arcade cabinet has a black and white monitor, a steering wheel and two foot pedals for gas and brake. The screen is completely black with white rectangles representing roadside poles. A monitor overlay sticker displays the car hood and boxes at the bottom of the screen for the distance, speed and misses. The player gets 90 seconds to drive across the finish line; crashing the car results in a time penalty. The game plays the sound of the engine and screaming tires.' FROM games WHERE igdb_id = 238207 ON CONFLICT (game_id, language_code) DO NOTHING;
