INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stunt Cycle', 'The game is housed in a custom cabinet that includes a simulated motorcycle steering column mounted on the control panel. The right side handle grip is twisted for acceleration. The monitor is a 19-inch black and white CRT monitor with a black and white overlay that adds giant tubes to the play field used to traverse from one split level to another. Sounds include a motorcycle roar, crash sounds, and crowd cheers. Stunt Cycle was ported to the AY-3-8760 custom chip by General Instruments and released by Atari as a dedicated console with bike handle controls. Sears released an Atari-manufactured version called Motocross.' FROM games WHERE igdb_id = 18584 ON CONFLICT (game_id, language_code) DO NOTHING;
