INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rock''n Bark', 'Rock''n Bark, sometimes erroneously labeled as "Rock''n Park", is a 1976 discrete logic game by Sega with twin Tommy Guns. It is similar to Sega''s earlier 1975 game Bullet Mark - complete with the "Bullet Mark" branding on the cabinet, suggesting it may have earlier been a cabinet variant or sequel.' FROM games WHERE igdb_id = 171853 ON CONFLICT (game_id, language_code) DO NOTHING;
