INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indy 4', 'The game is housed in a large custom square cabinet with two steering wheels and four pedals on each side. The monitor sits in the top of the cabinet. The game uses a full-color RGB display and does not use color overlays. The cabinet also features overhead mirrors to allow spectators to watch the game while it''s being played.' FROM games WHERE igdb_id = 18583 ON CONFLICT (game_id, language_code) DO NOTHING;
