INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tank 8', 'Tank 8 was produced by Kee Games in 1976. Kee Games released 16 different machines in our database under this trade name, starting in 1974. Other machines made by Kee Games during the time period Tank 8 was produced include Sprint 2, Quiz Show, Super Bug, Drag Race, Witch Hunt, Indy 800, Tank III, Formula K, Twin Racer, and Spike. Battle arena filled with barriers and "X"s that represent land mines is viewed from a overhead perspective by eight players who individually maneuver their uniquely colored tank in an effort to shoot the other. Tank 8 had two modes free-for-all and team-play. In free-for-all mode you get points for every kill. In team mode, tanks were red or blue and points were scored only for killing members of the opposite team. In a design that was ahead of its time, you did have to watch out to make sure you didn frag members of your own team.' FROM games WHERE igdb_id = 113933 ON CONFLICT (game_id, language_code) DO NOTHING;
