INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sparkling Corner', 'A four-player racing game by Sega. The four cars race along the screen in a side view, with collisions between them causing them to slow down. The winner is the car which has travelled the furthest during the allotted time.' FROM games WHERE igdb_id = 172521 ON CONFLICT (game_id, language_code) DO NOTHING;
