INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hockey', 'A ball-and-paddle game developed by General Instruments as one of the built-in games on their custom chips for dedicated consoles. It was included on the original custom chip released by GI in 1976, the AY-3-8500. An upgraded version of the game was included on the AY-3-8600 chip in 1977 featuring color and actual hockey goals. The novelty was that the ball could bounce behind these as well.' FROM games WHERE igdb_id = 68153 ON CONFLICT (game_id, language_code) DO NOTHING;
