INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demolition Derby', 'A black and white driving game where each player controls a pursuit car that tries to demolish drone cars to score points. Challenging and fast-moving super skill play, and never plays the same twice! Two target drones are always on the screen, darting around in competive evasive action as though they are controlled independantly. When a player has his or her car hit a drone, the drone is demolished and a point is scored. Drone wreckage remains on the screen and another comes into action. As drones pile up, each player must maneuver with increased speed and skill to increase his or her score before time is up. (Destruction Derby was the Exidy release from 1975, it was later licensed to and released by Chicago Coin as Demolition Derby in 1976)' FROM games WHERE igdb_id = 110847 ON CONFLICT (game_id, language_code) DO NOTHING;
