INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '280 Zzzap', 'The game is a simple black and white monochrome driving game. You control a car through a night time scene, and the road is represented by simple posts at the edges. The top of the screen will display information about upcoming curves (like the maximum safe speed to take them at), while the bottom of the screen has a speedometer, timer, scoreboard, and may also display a few tips as well. Just drive, and don''t crash. Pay attention to your speed on the corners to avoid crashing.' FROM games WHERE igdb_id = 19710 ON CONFLICT (game_id, language_code) DO NOTHING;
