INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Videocart-3: Video Blackjack', 'Videocart 3: Video Blackjack is a Casino video game released by Fairchild Semiconductor for the Fairchild Channel F in 1976. Think your system''s unbeatable? Wait''ll you see ours! Deal yourself into Video Blackjack for some fast action before you hit the big time.' FROM games WHERE igdb_id = 41220 ON CONFLICT (game_id, language_code) DO NOTHING;
